{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Verapamil has an absolute oral bioavailability of 34% in humans, above the 20% threshold, despite extensive first-pass metabolism; its physicochemical profile (basic amine, no HBD, moderate TPSA, MW near 455) is the closest experimental analogue to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Donepezil has 100% absolute oral bioavailability in humans, demonstrating that a basic CNS drug with no hydrogen-bond donors can achieve complete oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Valbenazine has approximately 49% absolute oral bioavailability in humans, supporting that a larger CNS-active molecule can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Almorexant has 11.2% absolute oral bioavailability, a low-F example; however, its higher molecular weight and different physicochemical properties limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Tetrabenazine has very low oral systemic availability (~5%) due to extensive first-pass metabolism, but its much smaller and less polar structure limits direct transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The most physicochemically similar experimental analogue, verapamil, supports F >=20% (absolute F ~20-34%), and high-F CNS drugs such as donepezil and valbenazine reinforce that basic, no-HBD CNS molecules can achieve adequate oral bioavailability. Low-F analogues (tetrabenazine, almorexant) are less transferable due to structural and physicochemical differences. Overall, high is better supported, though with uncertainty.",
  "evidence_gaps": [
    "No direct experimental measurement of absolute oral bioavailability for the exact query molecule.",
    "Uncertainty about the extent of first-pass metabolism for the query.",
    "Low neutral fraction (0.02) may affect passive absorption, but verapamil shows high absorption despite similar ionization, so the impact is unclear."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

